@php $title=(string)data_get($item,'title',data_get($item,'name','Sản phẩm'));$url=(string)data_get($item,'url','#');$img=(string)data_get($item,'image',data_get($item,'image_url',''));$price=(float)data_get($item,'price',0);$old=(float)data_get($item,'original_price',0); @endphp
<article class="dl-product-card"><a href="{{ $url }}"><img src="{{ $img }}" alt="{{ $title }}"></a><div><h3><a href="{{ $url }}">{{ $title }}</a></h3><p>@if($price>0)<b>{{ number_format($price,0,',','.') }}đ</b>@else<b>Liên hệ</b>@endif @if($old>$price)<del>{{ number_format($old,0,',','.') }}đ</del>@endif</p><a class="dl-cart" href="{{ $url }}">Xem sản phẩm <i class="fa-solid fa-arrow-right"></i></a></div></article>
